select pbi.id as bomId, pbi.serial_number, pbi.bom_version as bomVersion, pbs.parent_sku_id as parentSkuId, pbs.sku_id as skuId, pbs.sku_no as skuNo, pbs.quantity as quantity, pd.name as skuName, pd.unit_name as unitName from product_bom_info pbi left join product_bom_sku pbs on pbi.id = pbs.bom_id and pbs.is_deleted = false left join product_detail pd on pbs.sku_id = pd.id and pd.is_deleted = false
pbi.is_deleted = false and pbs.parent_sku_id in
#{item}

select pbi.id as bomId, pbi.bom_version as bomVersion, pbi.type AS type, pbs.parent_sku_id as parentSkuId, pbs.parent_sku_no as parentSkuNo, pbs.sku_id as skuId, pbs.sku_no as skuNo, pbs.quantity as quantity, pp.product_length as length, pp.product_width as width, pp.product_height as height, pp.gross_weight as grossWeight, pp.net_weight as netWeight, pd.name as skuName, pd.unit_name as unitName, pd.images_url as imageUrl from product_bom_info pbi left join product_bom_sku pbs on pbi.id = pbs.bom_id and pbs.is_deleted = false left join product_detail pd on pbs.sku_id = pd.id and pd.is_deleted = false left join product_pack pp on pp.sku_id = pbs.sku_id and pp.is_deleted = false
pbi.is_deleted = false and pbi.state = 4 and pbs.parent_sku_id in
#{item}

select pbi.id as bomId, pbi.type, pbi.bom_version as bomVersion, pbs.parent_sku_id as parentSkuId, pbs.parent_sku_no as parentSkuNo, pbs.sku_id as skuId, pbs.sku_no as skuNo, pbs.quantity as quantity, pp.product_length as productLength, pp.product_width as productWidth, pp.product_height as productHeight, pd.name as skuName, pd.unit_name as unitName from product_bom_info pbi left join product_bom_sku pbs on pbi.id = pbs.bom_id and pbs.is_deleted = false left join product_detail pd on pbs.sku_id = pd.id and pd.is_deleted = false left join product_pack pp on pp.sku_id = pbs.sku_id and pp.is_deleted = false WHERE pbi.is_deleted = false and pbi.state = 4
