select pbi.id as bomId, pbi.bom_version as bomVersion, pbi.type, pbs.parent_sku_id as parentSkuId, pbs.sku_id as skuId, pbs.sku_no as skuNo, pbs.quantity as quantity, pp.product_length as productLength, pp.product_width as productWidth, pp.product_height as productHeight, pd.name as skuName, pd.unit_name as unitName from product_bom_info pbi left join product_bom_sku pbs on pbi.id = pbs.bom_id and pbs.is_deleted = false left join product_detail pd on pbs.sku_id = pd.id and pd.is_deleted = false left join product_pack pp on pbs.sku_id = pp.sku_id and pp.is_deleted = false
