WITH RECURSIVE T ( sku_id,sku_no,parent_sku_id, parent_sku_no,quantity ) AS (
    SELECT sku_id,sku_no, parent_sku_id,parent_sku_no,quantity FROM product_bom_sku
    WHERE is_deleted = false

        and sku_id in

            #{item}



        and sku_no in

            #{item}


    UNION
    SELECT st.sku_id,st.sku_no,st.parent_sku_id,st.parent_sku_no,st.quantity
    FROM product_bom_sku st JOIN T ON st.sku_id = T.parent_sku_id and st.is_deleted = false
)
